const CACHE='atelier-v0.9.0';
const ASSETS=['./','./index.html','./style.css','./app.js?v=0.9.0','./chess.js','./move-review.js','./move-language.js','./position-language.js','./move-visuals.js','./compare-moves.js','./learning.js','./tactical-concepts.js','./recognizer.js','./board-vision.js','./oriented-sequence.js','./video-sequence.js','./recognition-edit.js','./recognition-resume.js','./templates-browser.json','./samples.json','./stockfish-19-lite-single.js','./stockfish-19-lite-single.wasm','./icon.svg','./cat-chess.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest',...['w','b'].flatMap(c=>['p','n','b','r','q','k'].map(p=>'./pieces/'+c+p+'.svg'))];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS.map(url=>new Request(url,{cache:'reload'})))).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(u.origin!==location.origin||e.request.method!=='GET'||u.pathname.endsWith('version.json'))return;e.respondWith(caches.open(CACHE).then(c=>c.match(e.request)).then(cached=>cached||fetch(e.request)))});
